const lv_image_dsc_t *spippy_face_find(const char *name)
{
    if (name == NULL) {
        name = "neutral";
    }
    for (size_t i = 0; i < sizeof(kSpippyFaces) / sizeof(kSpippyFaces[0]); ++i) {
        if (strcmp(kSpippyFaces[i].name, name) == 0) {
            return kSpippyFaces[i].image;
        }
    }
    return spippy_face_find("neutral");
}

bool spippy_face_exists(const char *name)
{
    if (name == NULL) {
        return false;
    }
    for (size_t i = 0; i < sizeof(kSpippyFaces) / sizeof(kSpippyFaces[0]); ++i) {
        if (strcmp(kSpippyFaces[i].name, name) == 0) {
            return true;
        }
    }
    return false;
}

const spippy_face_resource_t *spippy_face_resources(size_t *count)
{
    if (count != NULL) {
        *count = sizeof(kSpippyFaces) / sizeof(kSpippyFaces[0]);
    }
    return kSpippyFaces;
}
